<script setup lang="ts">
import { reactive, ref } from 'vue';
import { router } from '@inertiajs/vue3';
import { Search, Megaphone } from 'lucide-vue-next';
import AdminLayout from '@/layouts/AdminLayout.vue';
import { Card, CardContent } from '@/components/ui/card';
import type { EtmsSharedProps } from '@/types/etms';
interface Announcement{id:number;title:string;body:string;audienceType:string;audienceLabel:string;trainingSessionId:number|null;moduleId:number|null;targetRole:string|null;sendEmail:boolean;sendInApp:boolean;status:string;statusLabel:string;recipients:number;sentAt:string|null}
interface Option{value:string;label:string};interface Entity{id:number;label:string}
interface Props extends EtmsSharedProps{announcements:{data:Announcement[];from:number|null;to:number|null;total:number;links:{url:string|null;label:string;active:boolean}[]};filters:{q:string;status:string};statuses:Option[];roles:Option[];sessions:Entity[];modules:Entity[]}
const props=defineProps<Props>();const filters=reactive({...props.filters});const editing=ref<Announcement|null>(null);
const form=reactive<{title:string;body:string;audience_type:string;training_session_id:number|' ';module_id:number|' ';target_role:string;send_email:boolean;send_in_app:boolean}>({title:'',body:'',audience_type:'all_customers',training_session_id:' ',module_id:' ',target_role:'',send_email:true,send_in_app:true});
function apply(){router.get('/admin-vue/announcements',filters,{preserveState:true,replace:true})}
function beginCreate(){editing.value=null;Object.assign(form,{title:'',body:'',audience_type:'all_customers',training_session_id:' ',module_id:' ',target_role:'',send_email:true,send_in_app:true})}
function beginEdit(a:Announcement){editing.value=a;Object.assign(form,{title:a.title,body:a.body,audience_type:a.audienceType,training_session_id:a.trainingSessionId??' ',module_id:a.moduleId??' ',target_role:a.targetRole??'',send_email:a.sendEmail,send_in_app:a.sendInApp})}
function save(){const data={...form,training_session_id:form.training_session_id===' '?null:form.training_session_id,module_id:form.module_id===' '?null:form.module_id,target_role:form.target_role||null};if(editing.value)router.post(`/admin-vue/announcements/${editing.value.id}`,data,{preserveScroll:true,onSuccess:beginCreate});else router.post('/admin-vue/announcements',data,{preserveScroll:true,onSuccess:beginCreate})}
</script>
<template><AdminLayout><div class="mb-6"><p class="text-sm font-medium text-[#0F4C81]">Content administration</p><h1 class="mt-1 text-2xl font-semibold">Announcements</h1></div><div class="grid gap-6 lg:grid-cols-[22rem_minmax(0,1fr)]"><Card><CardContent class="p-4"><h2 class="mb-4 font-semibold">{{editing?'Edit announcement':'New announcement'}}</h2><form class="space-y-3" @submit.prevent="save">
<label class="block text-sm">Title<input v-model="form.title" required maxlength="200" class="mt-1 h-10 w-full rounded-md border px-3"/></label><label class="block text-sm">Message<textarea v-model="form.body" required rows="5" maxlength="10000" class="mt-1 w-full rounded-md border px-3 py-2"/></label>
<label class="block text-sm">Audience<select v-model="form.audience_type" class="mt-1 h-10 w-full rounded-md border px-3"><option value="all_customers">All active customers</option><option value="session_participants">Session participants and instructors</option><option value="module_entitled_users">Module entitled users</option><option value="role">Specific role</option></select></label>
<label v-if="form.audience_type==='session_participants'" class="block text-sm">Session<select v-model="form.training_session_id" required class="mt-1 h-10 w-full rounded-md border px-3"><option value=" ">Select session</option><option v-for="s in sessions" :key="s.id" :value="s.id">{{s.label}}</option></select></label>
<label v-if="form.audience_type==='module_entitled_users'" class="block text-sm">Module<select v-model="form.module_id" required class="mt-1 h-10 w-full rounded-md border px-3"><option value=" ">Select module</option><option v-for="m in modules" :key="m.id" :value="m.id">{{m.label}}</option></select></label>
<label v-if="form.audience_type==='role'" class="block text-sm">Role<select v-model="form.target_role" required class="mt-1 h-10 w-full rounded-md border px-3"><option value="">Select role</option><option v-for="r in roles" :key="r.value" :value="r.value">{{r.label}}</option></select></label>
<label class="flex gap-2 text-sm"><input v-model="form.send_email" type="checkbox"/> Send email</label><label class="flex gap-2 text-sm"><input v-model="form.send_in_app" type="checkbox"/> Send in-app notification</label>
<div class="flex gap-2"><button class="h-10 rounded-md bg-[#0F4C81] px-4 text-sm text-white">{{editing?'Save':'Create draft'}}</button><button v-if="editing" type="button" class="h-10 rounded-md border px-3 text-sm" @click="beginCreate">Cancel</button></div>
</form></CardContent></Card><Card><CardContent class="p-4"><form class="grid gap-3 md:grid-cols-[minmax(0,1fr)_10rem_auto]" @submit.prevent="apply"><label class="relative"><Search class="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" :size="16"/><input v-model="filters.q" class="h-10 w-full rounded-md border pl-9 text-sm" placeholder="Announcement title"/></label><select v-model="filters.status" class="h-10 rounded-md border px-3 text-sm"><option value="">All statuses</option><option v-for="s in statuses" :key="s.value" :value="s.value">{{s.label}}</option></select><button class="h-10 rounded-md bg-slate-900 px-4 text-sm text-white">Apply</button></form>
<div class="mt-4 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="border-b bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-3 py-3">Announcement</th><th class="px-3 py-3">Audience</th><th class="px-3 py-3">Status</th><th class="px-3 py-3">Actions</th></tr></thead><tbody class="divide-y"><tr v-for="a in announcements.data" :key="a.id"><td class="px-3 py-4"><div class="font-medium">{{a.title}}</div><div class="text-xs text-slate-500">{{a.recipients}} recipients</div></td><td class="px-3 py-4">{{a.audienceLabel}}</td><td class="px-3 py-4">{{a.statusLabel}}</td><td class="px-3 py-4"><div class="flex flex-wrap gap-2"><button v-if="a.status!== 'sent'" class="rounded-md border px-2 py-1 text-xs" @click="beginEdit(a)">Edit</button><button v-if="['draft','scheduled','failed'].includes(a.status)" class="rounded-md bg-emerald-700 px-2 py-1 text-xs text-white" @click="router.post(`/admin-vue/announcements/${a.id}/send`,{}, {preserveScroll:true})">Send now</button><button v-if="a.status==='draft'" class="rounded-md border border-red-200 px-2 py-1 text-xs text-red-700" @click="router.delete(`/admin-vue/announcements/${a.id}`,{preserveScroll:true})">Delete</button></div></td></tr><tr v-if="!announcements.data.length"><td colspan="4" class="p-12 text-center text-slate-500"><Megaphone class="mx-auto mb-2" :size="24"/>No announcements found.</td></tr></tbody></table></div></CardContent></Card></div></AdminLayout></template>
